CREATE OR REPLACE FUNCTION public.pm_quote_internal_fee(_quote uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce(sum(CASE WHEN coalesce(nullif(s.sale_source,''),q.fee_source_mode,'allocation')='budget' THEN coalesce(s.budget,0) ELSE coalesce((SELECT sum((SELECT count(*) FROM generate_series(a.start_date::timestamp,a.end_date::timestamp,interval '1 day') d WHERE extract(isodow FROM d)<6)*a.hours_per_day*a.sale_rate_snapshot) FROM quote_allocations a WHERE a.stage_id=s.id),0) END),0)*coalesce(nullif(q.pricing_multiplier,0),1) FROM fee_proposals q LEFT JOIN quote_stages s ON s.quote_id=q.id AND NOT EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=s.id) WHERE q.id=_quote GROUP BY q.pricing_multiplier $$;
CREATE OR REPLACE FUNCTION public.pm_quote_external_fee(_quote uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce(sum(e.sale_price*e.quantity*(1+coalesce((SELECT m.markup_pct FROM quote_supplier_markups m WHERE m.quote_id=_quote AND (m.supplier_company_id=e.supplier_company_id OR (m.supplier_company_id IS NULL AND m.supplier_id=e.supplier_id) OR (m.supplier_company_id IS NULL AND m.supplier_id IS NULL AND lower(trim(m.supplier_label))=lower(trim(e.description)))) ORDER BY CASE WHEN m.supplier_company_id IS NOT NULL THEN 0 WHEN m.supplier_id IS NOT NULL THEN 1 ELSE 2 END LIMIT 1),0)/100)),0)*coalesce(nullif(q.pricing_multiplier,0),1) FROM fee_proposals q LEFT JOIN quote_external_services e ON e.quote_id=q.id WHERE q.id=_quote GROUP BY q.pricing_multiplier $$;
REVOKE ALL ON FUNCTION public.pm_quote_internal_fee(uuid),public.pm_quote_external_fee(uuid) FROM PUBLIC,anon,authenticated;
DO $migration$ DECLARE definition text; start_at integer; end_at integer; BEGIN SELECT pg_get_functiondef('public.pm_convert_relative_quote(uuid,date,text)'::regprocedure) INTO definition; start_at:=strpos(definition,'SELECT coalesce(sum(CASE'); end_at:=strpos(definition,'INSERT INTO pm_projects'); IF start_at=0 OR end_at<=start_at THEN RAISE EXCEPTION 'Unexpected conversion definition'; END IF; definition:=left(definition,start_at-1)||'internal_fee:=pm_quote_internal_fee(_quote); external_fee:=pm_quote_external_fee(_quote); IF internal_fee=0 AND q.time_based_settings->>''kind''=''consultancy_hours_package'' THEN internal_fee:=coalesce((q.time_based_settings->>''hourly_rate'')::numeric,0)*coalesce((q.time_based_settings->>''hours_block'')::numeric,0)*multiplier; ELSIF internal_fee=0 AND q.time_based_settings->>''kind''=''construction_retainer'' THEN internal_fee:=coalesce((SELECT sum((r->>''hours_per_month'')::numeric*(r->>''hourly_rate'')::numeric) FROM jsonb_array_elements(coalesce(q.time_based_settings->''monthly_resources'',''[]''::jsonb)) r),0)*greatest(1,coalesce((q.time_based_settings->>''construction_duration_months'')::integer,1))*multiplier; END IF;'||chr(10)||substr(definition,end_at); definition:=replace(definition,'quote_payment_schedule_items,quote_external_services IN SHARE ROW EXCLUSIVE MODE','quote_payment_schedule_items,quote_external_services,quote_supplier_markups,holidays IN SHARE ROW EXCLUSIVE MODE'); EXECUTE definition; END $migration$;